{
  "root": "main",
  "state": {
    "salesData": [
      { "month": "Jan 2026", "north": 120, "south": 90, "east": 75, "west": 105, "total": 390 },
      { "month": "Feb 2026", "north": 130, "south": 88, "east": 82, "west": 110, "total": 410 },
      { "month": "Mar 2026", "north": 125, "south": 95, "east": 79, "west": 118, "total": 417 },
      { "month": "Apr 2026", "north": 140, "south": 100, "east": 90, "west": 121, "total": 451 }
    ]
  },
  "elements": {
    "main": { "type": "Stack", "props": { "direction": "vertical", "gap": "md", "padding": 16 }, "children": ["title", "summary", "tableSection", "insightsTitle", "insight1", "insight2", "insight3", "actions", "sources"] },
    "title": { "type": "Text", "props": { "text": "Monthly Sales Dashboard Overview", "variant": "h1" }, "children": [] },
    "summary": { "type": "Text", "props": { "text": "The dataset shows steady overall growth from Jan to Apr 2026, with North leading every month and East showing the fastest relative improvement.", "variant": "body" }, "children": [] },
    "tableSection": { "type": "Table", "props": { "title": "Monthly Sales Breakdown", "statePath": "/salesData", "columns": [{ "key": "month", "label": "Month" }, { "key": "north", "label": "North" }, { "key": "south", "label": "South" }, { "key": "east", "label": "East" }, { "key": "west", "label": "West" }, { "key": "total", "label": "Total" }], "domain": "generic", "preferredPresentation": "table" }, "children": [] },
    "insightsTitle": { "type": "Text", "props": { "text": "Key Insights", "variant": "h2" }, "children": [] },
    "insight1": { "type": "Text", "props": { "text": "Overall growth is positive and consistent: total sales rose from 390 in January to 451 in April, a gain of 61 or about 15.6%." }, "children": [] },
    "insight2": { "type": "Text", "props": { "text": "North remains the top performer: it increased from 120 to 140, staying ahead of all regions." }, "children": [] },
    "insight3": { "type": "Text", "props": { "text": "East is the strongest momentum story: it grew from 75 to 90, a 20% increase." }, "children": [] },
    "actions": { "type": "Stack", "props": { "direction": "horizontal", "gap": "md" }, "children": ["btn1", "btn2"] },
    "btn1": { "type": "Button", "props": { "label": "Build Dashboard", "on": { "press": { "action": "openUrl", "params": { "url": "https://www.microsoft.com/en-us/power-platform/products/power-bi" } } } }, "children": [] },
    "btn2": { "type": "Button", "props": { "label": "Export Data", "on": { "press": { "action": "openUrl", "params": { "url": "https://www.google.com/sheets/about/" } } } }, "children": [] },
    "sources": { "type": "Stack", "props": { "direction": "vertical", "gap": "sm" }, "children": ["sourceTitle", "sourceBtn1", "sourceBtn2"] },
    "sourceTitle": { "type": "Text", "props": { "text": "Sources", "variant": "h3" }, "children": [] },
    "sourceBtn1": { "type": "Button", "props": { "label": "Chart guidance", "on": { "press": { "action": "openUrl", "params": { "url": "https://www.datawrapper.de/blog/best-chart-types/" } } } }, "children": [] },
    "sourceBtn2": { "type": "Button", "props": { "label": "Dashboard design principles", "on": { "press": { "action": "openUrl", "params": { "url": "https://www.nngroup.com/articles/dashboard-design/" } } } }, "children": [] }
  }
}
